INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (211, 1, '파일을 Pod 로 보내고 가져오기', '`kubectl cp` 로 내 컴퓨터의 `./a.txt` 를 Pod `p1` 의 `/tmp/a.txt` 로 보내려면 어떻게 쓰고, Pod 의 `/tmp/b.txt` 를 내 컴퓨터로 가져오려면 어떻게 쓸까요?', '앞이 원본, 뒤가 목적지예요.', NULL, NULL, '[]', 'choice', '["보낼 때는 `kubectl cp p1:/tmp/a.txt ./a.txt` 로 쓰고 가져올 때는 `kubectl cp ./b.txt p1:/tmp/b.txt` 로 쓴다", "방향과 상관없이 항상 Pod 이름을 첫 번째에 쓴다", "보낼 때는 `kubectl cp ./a.txt p1:/tmp/a.txt`, 가져올 때는 `kubectl cp p1:/tmp/b.txt ./b.txt` 이다. 앞이 원본, 뒤가 목적지이고 Pod 쪽은 `Pod이름:경로` 로 쓴다", "`kubectl cp` 는 가져오기만 되고 보내기는 `kubectl upload` 를 써야 한다"]', 2, '다른 네임스페이스의 Pod 는 `네임스페이스/Pod:경로` 로 쓸 수 있고, `-n` 으로 네임스페이스를 줘도 됩니다.', NULL, NULL, NULL, NULL),
  (211, 2, 'cp 할 때 나오는 tar 메시지', 'Pod 의 파일을 가져오는데 `tar: removing leading ''/'' from member names` 라는 메시지가 나왔습니다. 파일은 어떻게 되었을까요?', '경고일 뿐 실패 메시지가 아니에요.', NULL, NULL, '[]', 'choice', '["복사가 실패했으니 파일이 없다", "맨 앞의 `/` 를 떼고 저장한다는 안내(경고)일 뿐이고 파일은 정상적으로 복사된다. `kubectl cp` 는 내부에서 `tar` 를 쓴다", "파일은 복사되지만 내용이 비어 있다", "Pod 의 `/` 아래 파일이 모두 지워진다"]', 1, '이 메시지는 `kubectl cp` 가 내부에서 `tar` 로 묶어 옮기기 때문에 나옵니다.', NULL, NULL, NULL, NULL),
  (211, 3, 'kubectl wait 가 성공하면', '`kubectl wait --for=condition=Ready pod/p1 --timeout=60s` 를 했더니 Pod 가 준비되었습니다. 무엇이 출력되고 종료 코드는 얼마일까요?', '조건이 맞으면 한 줄 알려 줘요.', NULL, NULL, '[]', 'choice', '["`pod/p1 condition met` 이 출력되고 종료 코드는 `0` 이다", "`pod/p1 Ready` 가 출력되고 종료 코드는 `1` 이다", "아무것도 출력하지 않고 종료 코드는 `1` 이다", "`pod/p1 created` 가 출력되고 종료 코드는 `0` 이다"]', 0, '스크립트에서 Pod 가 준비된 뒤에 다음 명령을 실행할 때 씁니다.', NULL, NULL, NULL, NULL),
  (211, 4, 'kubectl wait 시간 초과', '`kubectl wait --for=condition=Ready pod/p2 --timeout=1s` 를 했는데 1초 안에 준비되지 않았습니다. 결과는 어떨까요?', '기다리다 포기하면 오류예요.', NULL, NULL, '[]', 'choice', '["`condition met` 이 출력되고 종료 코드는 `0` 이다", "Pod 가 자동으로 삭제된다", "계속 기다리며 `--timeout` 은 무시된다", "`error: timed out waiting for the condition on pods/p2` 오류가 나고 종료 코드는 `1` 이다. 이후 Pod 가 준비되어도 이 명령은 이미 실패로 끝난 것이다"]', 3, '`--timeout` 은 기다릴 최대 시간입니다.', NULL, NULL, NULL, NULL),
  (211, 5, '지워질 때까지 기다리기', 'Pod `p2` 를 `kubectl delete pod p2 --wait=false` 로 지우고, 완전히 사라질 때까지 기다리려면 어떤 명령을 쓸까요?', '조건 대신 `delete` 를 줘요.', NULL, NULL, '[]', 'choice', '["`kubectl wait --for=condition=Deleted pod/p2` 를 쓴다", "`kubectl wait --for=gone pod/p2` 를 쓴다", "`kubectl wait --for=delete pod/p2 --timeout=60s` 를 쓰면 사라질 때 `condition met` 이 출력되고 종료 코드 `0` 으로 끝난다", "삭제는 기다릴 수 없고 `kubectl get pod p2` 를 반복해야 한다"]', 2, '`--wait=false` 는 지우는 명령이 삭제 완료를 기다리지 않고 바로 돌아오게 합니다.', NULL, NULL, NULL, NULL),
  (211, 6, 'replace 로 없는 것 바꾸기', '클러스터에 없는 ConfigMap `c1` 의 YAML 로 `kubectl replace -f cm.yaml` 을 하면 어떻게 될까요?', 'replace 는 이미 있는 것만 바꿔요.', NULL, NULL, '[]', 'choice', '["ConfigMap 이 새로 만들어진다", "`configmaps \\"c1\\" not found` 라는 NotFound 오류가 난다. `replace` 는 이미 있는 리소스만 바꾸므로 만들려면 `create` 나 `apply` 를 쓴다", "아무 오류 없이 아무것도 하지 않는다", "`already exists` 오류가 난다"]', 1, '`apply` 는 없으면 만들고 있으면 바꿉니다.', NULL, NULL, NULL, NULL),
  (211, 7, 'replace --force', '이미 있는 ConfigMap 에 `kubectl replace --force -f cm.yaml` 을 하면 무슨 일이 일어날까요?', '지우고 다시 만들어요.', NULL, NULL, '[]', 'choice', '["기존 것을 지운 뒤 다시 만든다. 출력에 `deleted` 와 `replaced` 가 차례로 보이고 새로 만들어졌으므로 uid 가 바뀐다", "지우지 않고 값만 덮어쓰며 uid 는 그대로이다", "`already exists` 오류가 나고 아무것도 바뀌지 않는다", "기존 ConfigMap 은 `c1.bak` 이름으로 남는다"]', 0, '보통은 `apply` 나 `replace` 로 충분하고 `--force` 는 꼭 필요할 때만 씁니다.', NULL, NULL, NULL, NULL),
  (211, 8, 'apply 출력 세 가지', '`kubectl apply -f cm.yaml` 의 출력이 `created`, `unchanged`, `configured` 로 나옵니다. 각각은 언제일까요?', '없었다 / 같다 / 달랐다 로 나눠요.', NULL, NULL, '[]', 'choice', '["`created` 는 같은 내용일 때, `unchanged` 는 새로 만들 때, `configured` 는 오류일 때이다", "세 가지는 모두 같은 뜻이고 실행 횟수만 다르다", "`configured` 는 `apply` 가 실패했다는 뜻이다", "없어서 새로 만들면 `created`, 내용이 같아서 바꿀 것이 없으면 `unchanged`, 내용이 달라서 고치면 `configured` 이다"]', 3, '`apply` 를 같은 파일로 다시 해도 안전한 이유가 이 동작입니다.', NULL, NULL, NULL, NULL),
  (211, 9, 'kubectl diff 의 종료 코드', '`kubectl diff -f cm.yaml` 은 파일과 클러스터의 내용이 같을 때와 다를 때 종료 코드가 각각 얼마일까요? 이 명령은 클러스터를 바꿀까요?', '차이가 있으면 0 이 아니에요.', NULL, NULL, '[]', 'choice', '["같으면 `1`, 다르면 `0` 이다", "다르면 파일 내용이 클러스터에 자동으로 적용된다", "같으면 `0`, 다르면 `1` 이다. 차이를 보여 주기만 하고 클러스터는 바꾸지 않으며 없는 리소스도 만들지 않는다. 바꾸려면 `apply` 를 해야 한다", "항상 `0` 이고 차이는 출력으로만 알 수 있다"]', 2, '차이는 `-` 줄(현재)과 `+` 줄(적용 후)로 보입니다.', NULL, NULL, NULL, NULL),
  (211, 10, 'api-resources 읽기', '`kubectl api-resources` 에서 `cm`, `svc`, `deploy` 는 어느 열에 나올까요? `NAMESPACED` 가 `false` 인 것은 무엇을 뜻할까요?', '열 이름은 NAME, SHORTNAMES, APIVERSION, NAMESPACED, KIND 예요.', NULL, NULL, '[]', 'choice', '["`KIND` 열의 값이고 `NAMESPACED` 가 `false` 이면 삭제할 수 없다는 뜻이다", "`SHORTNAMES` 열의 줄임말이다. `NAMESPACED` 가 `false` 인 `nodes`, `namespaces` 같은 것은 네임스페이스에 속하지 않고 클러스터 전체에 하나씩 있다", "`APIVERSION` 열의 값이고 `NAMESPACED` 가 `false` 이면 비활성이라는 뜻이다", "`NAME` 열의 값이고 `NAMESPACED` 가 `false` 이면 `-n` 이 필수라는 뜻이다"]', 1, '`kubectl api-resources --namespaced=false` 로 클러스터 전체 범위 종류만 볼 수 있습니다.', NULL, NULL, NULL, NULL),
  (211, 11, 'kubectl edit 로 고치기', '`kubectl edit cm c1` 로 에디터를 열었다가 아무것도 바꾸지 않고 저장 후 닫으면 무슨 메시지가 나올까요? 값을 바꾸고 저장하면요?', '바꾼 것이 없으면 취소로 처리돼요.', NULL, NULL, '[]', 'choice', '["바꾸지 않으면 `Edit cancelled, no changes made.`, 값을 바꾸고 저장하면 `configmap/c1 edited` 가 출력되고 바로 클러스터에 반영된다", "바꾸지 않아도 항상 `configmap/c1 edited` 가 출력된다", "바꿔도 `kubectl apply` 를 해야 반영된다", "에디터를 닫으면 항상 `Edit cancelled` 가 출력된다"]', 0, '에디터는 `KUBE_EDITOR` 환경 변수로 정할 수 있습니다.', NULL, NULL, NULL, NULL),
  (211, 12, '강제 삭제', '`kubectl delete pod p3 --grace-period=0 --force` 를 하면 무엇이 출력되고, 바로 `kubectl get pod p3` 를 하면 어떻게 될까요?', '경고가 먼저 나와요.', NULL, NULL, '[]', 'choice', '["경고 없이 종료되고 Pod 는 잠시 `Terminating` 으로 남는다", "`--force` 는 Pod 가 아니라 Deployment 만 지울 수 있다", "아무 출력이 없고 Pod 는 그대로 남아 있다", "`Warning: Immediate deletion does not wait for confirmation that the running resource has been terminated.` 경고와 `force deleted` 가 출력되고, 바로 조회하면 `NotFound` 이다. 컨테이너가 실제로 끝났는지는 기다리지 않으므로 평소에는 쓰지 않는다"]', 3, '평소에는 `kubectl delete pod p3` 로 지우는 것이 안전합니다.', NULL, NULL, NULL, NULL),
  (211, 13, '라벨 덮어쓰기와 지우기', '`env=dev` 라벨이 붙은 Pod 에 `kubectl label pod p4 env=prod` 를 하면 어떻게 될까요? 값을 바꾸려면, 라벨을 지우려면 어떻게 할까요?', '같은 키의 다른 값은 막혀 있어요.', NULL, NULL, '[]', 'choice', '["오류 없이 `env=prod` 로 바로 바뀌고 지울 때는 `--delete` 를 쓴다", "`env=dev` 와 `env=prod` 가 함께 붙는다", "`''env'' already has a value (dev), and --overwrite is false` 오류가 난다. 바꾸려면 `--overwrite` 를 붙이고, 지우려면 키 뒤에 `-` 를 붙여 `kubectl label pod p4 env-` 로 쓴다", "오류가 나며 라벨은 한 번 붙이면 바꾸거나 지울 수 없다"]', 2, '`kubectl get pod --show-labels` 로 라벨을 확인할 수 있습니다.', NULL, NULL, NULL, NULL),
  (211, 14, '라벨 선택자 읽기', 'Pod `a1`(`env=dev`, `tier=web`), `a2`(`env=prod`, `tier=web`), `a3`(`env=prod`) 만 있다고 합니다. `-l env=prod,tier=web` 과 `-l ''!tier''` 는 각각 어느 Pod 를 고를까요?', '쉼표는 "그리고"예요.', NULL, NULL, '[]', 'choice', '["`env=prod,tier=web` 은 `a2` 와 `a3` 이고 `!tier` 는 `a1` 과 `a2` 이다", "`env=prod,tier=web` 은 두 조건을 모두 만족하는 `a2` 이고, `!tier` 는 `tier` 라벨이 아예 없는 `a3` 이다", "`env=prod,tier=web` 은 `a1`, `a2`, `a3` 모두이고 `!tier` 는 아무것도 고르지 못한다", "`env=prod,tier=web` 은 `a1` 이고 `!tier` 는 `a2` 이다"]', 1, '`-l ''env in (dev,prod)''` 처럼 여러 값 중 하나를 고를 수도 있습니다.', NULL, NULL, NULL, NULL),
  (211, 15, '파일 복사하기', '`kubectl` 로 **파일을 Pod 로 복사하는** 하위 명령을 채우세요.', '"copy"를 두 글자로 줄여요.', NULL, NULL, '[]', 'fill', '["cp", "copy", "push", "upload"]', NULL, '방향을 바꿔 `kubectl cp p1:/tmp/a.txt ./a.txt` 처럼 쓰면 가져옵니다.', '[0]', 'kubectl {0} ./a.txt p1:/tmp/a.txt', NULL, NULL),
  (211, 16, '준비될 때까지 기다리기', '조건이 맞을 때까지 **기다리는** `kubectl` 하위 명령을 채우세요.', '"기다리다"를 영어로 써요.', NULL, NULL, '[]', 'fill', '["wait", "watch", "until", "hold"]', NULL, '시간 안에 조건이 맞지 않으면 오류로 끝납니다.', '[0]', 'kubectl {0} --for=condition=Ready pod/p1 --timeout=60s', NULL, NULL),
  (211, 17, '기다릴 조건', '`kubectl wait` 의 `--for=` 뒤에 **조건 이름을 지정하는** 단어를 채우세요.', '"조건"을 영어로 써요.', NULL, NULL, '[]', 'fill', '["condition", "status", "phase", "state"]', NULL, '삭제를 기다릴 때는 `--for=delete` 를 씁니다.', '[0]', 'kubectl wait --for={0}=Ready pod/p1', NULL, NULL),
  (211, 18, '이미 있는 것 바꾸기', '이미 있는 리소스를 **파일 내용으로 바꾸는** 하위 명령을 채우세요.', '"바꾸다"를 영어로 써요.', NULL, NULL, '[]', 'fill', '["replace", "change", "update", "swap"]', NULL, '없는 리소스에 쓰면 NotFound 오류가 납니다.', '[0]', 'kubectl {0} -f cm.yaml', NULL, NULL),
  (211, 19, '지우고 다시 만들기', '`replace` 에서 **기존 것을 지우고 다시 만들게 하는** 옵션을 채우세요.', '"억지로"를 뜻하는 영어예요.', NULL, NULL, '[]', 'fill', '["--force", "--again", "--recreate", "--reset"]', NULL, '다시 만들어지므로 uid 가 바뀝니다.', '[0]', 'kubectl replace {0} -f cm.yaml', NULL, NULL),
  (211, 20, '적용 전 차이 보기', '`apply` 하기 전에 **바뀔 내용만 미리 보여 주는** 하위 명령을 채우세요.', '"차이"를 뜻하는 영어예요.', NULL, NULL, '[]', 'fill', '["diff", "compare", "preview", "check"]', NULL, '차이가 있으면 종료 코드 `1` 입니다.', '[0]', 'kubectl {0} -f cm.yaml', NULL, NULL),
  (211, 21, '리소스 종류 목록', '클러스터가 지원하는 **리소스 종류와 줄임말을 보여 주는** 하위 명령을 채우세요.', '"api"와 "resources"를 이어요.', NULL, NULL, '[]', 'fill', '["api-resources", "api-list", "resources", "kinds"]', NULL, '`SHORTNAMES` 열에서 줄임말을 볼 수 있습니다.', '[0]', 'kubectl {0}', NULL, NULL),
  (211, 22, '라벨 덮어쓰기', '이미 있는 키의 라벨 값을 **바꾸도록 허용하는** 옵션을 채우세요.', '"덮어쓰다"를 영어로 써요.', NULL, NULL, '[]', 'fill', '["--overwrite", "--force", "--replace", "--update"]', NULL, '없으면 `already has a value` 오류가 납니다.', '[0]', 'kubectl label pod p4 env=prod {0}', NULL, NULL),
  (211, 23, '라벨 지우기', 'Pod `p4` 에서 `env` **라벨을 지우는** 인자를 채우세요.', '키 이름 뒤에 빼기 기호를 붙여요.', NULL, NULL, '[]', 'fill', '["env-", "env=", "-env", "env!"]', NULL, '지운 뒤 `--show-labels` 로 확인합니다.', '[0]', 'kubectl label pod p4 {0}', NULL, NULL),
  (211, 24, '끝에서 몇 줄만', '로그의 **마지막 몇 줄만** 보여 주는 옵션 이름을 채우세요.', '"꼬리"를 영어로 써요.', NULL, NULL, '[]', 'fill', '["tail", "last", "lines", "head"]', NULL, '`--since=1h` 는 최근 1시간만 보여 줍니다.', '[0]', 'kubectl logs p4 --{0}=2', NULL, NULL),
  (211, 25, '컨텍스트 바꾸기', '사용할 **컨텍스트를 바꾸는** `kubectl config` 하위 명령의 앞부분을 채우세요.', '"사용하다"를 영어로 써요.', NULL, NULL, '[]', 'fill', '["use", "switch", "change", "select"]', NULL, '현재 컨텍스트는 `kubectl config current-context` 로 봅니다.', '[0]', 'kubectl config {0}-context mycluster', NULL, NULL),
  (211, 26, '파일 주고받기', 'Pod 에 파일을 보내고 다시 가져와 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', 'Pod 준비 → 보내기 → 확인 → 가져오기 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl run p1 --image=busybox:1.36 -- sleep 3600` 로 Pod 를 만들고 `kubectl wait --for=condition=Ready pod/p1` 로 준비를 기다린다", "`kubectl cp ./a.txt p1:/tmp/a.txt` 로 파일을 Pod 로 보낸다", "`kubectl exec p1 -- cat /tmp/a.txt` 로 내용이 들어갔는지 확인한다", "`kubectl cp p1:/tmp/a.txt ./back.txt` 로 다시 가져와 내용이 같은지 본다"]', NULL, '폴더도 같은 방식으로 `kubectl cp ./dir p1:/tmp/dir` 처럼 복사됩니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (211, 27, 'apply 전에 차이 확인', '파일을 적용하기 전에 차이를 확인하고 적용하는 순서입니다. 순서에 맞게 놓아 보세요.', 'diff → apply → 다시 diff → 값 확인 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl diff -f cm.yaml` 로 바뀔 줄(`-`, `+`)을 확인한다. 종료 코드는 `1` 이다", "`kubectl apply -f cm.yaml` 로 적용하고 `configured` 가 나오는지 본다", "`kubectl diff -f cm.yaml` 을 다시 해서 출력이 없고 종료 코드가 `0` 인지 확인한다", "`kubectl get cm c1 -o jsonpath=''{.data}''` 로 실제 값이 바뀌었는지 확인한다"]', NULL, '`diff` 만으로는 클러스터가 바뀌지 않습니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (211, 28, '라벨 붙이고 바꾸고 지우기', 'Pod 의 라벨을 다루는 순서입니다. 순서에 맞게 놓아 보세요.', '붙이기 → 같은 키 오류 → 덮어쓰기 → 지우기 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl label pod p4 env=dev` 로 라벨을 붙인다", "`kubectl label pod p4 env=prod` 를 해서 `--overwrite is false` 오류가 나는지 본다", "`kubectl label pod p4 env=prod --overwrite` 로 값을 바꾸고 `--show-labels` 로 확인한다", "`kubectl label pod p4 env-` 로 라벨을 지우고 다시 확인한다"]', NULL, '라벨 선택자 `-l env=prod` 로 같은 라벨의 Pod 를 한꺼번에 고를 수 있습니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (211, 29, '컨텍스트와 네임스페이스 바꾸기', '사용 중인 컨텍스트를 확인하고 기본 네임스페이스를 바꾸는 순서입니다. 순서에 맞게 놓아 보세요.', '목록 → 현재 → 네임스페이스 설정 → 확인 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl config get-contexts` 로 컨텍스트 목록과 `*` 표시를 본다", "`kubectl config current-context` 로 지금 쓰는 컨텍스트 이름을 확인한다", "`kubectl config set-context --current --namespace=dev` 로 기본 네임스페이스를 바꾼다", "`-n` 없이 `kubectl get cm` 을 해서 `dev` 네임스페이스의 것이 나오는지 확인한다"]', NULL, '`set-context --current` 는 새 컨텍스트를 만들지 않고 지금 것을 고칩니다.', '[0, 1, 2, 3]', NULL, NULL, NULL);
